+      const auto params = TpCombineParams{
+          .residual = static_cast<bf16_t*>(residual.data_ptr()),
+          .values = values,
+          .gates = gates,
+          .pre = static_cast<const float*>(pre.data_ptr()),
+          .norm_weight = static_cast<const bf16_t*>(weight.data_ptr()),
