+template <uint32_t kRowsPerCTA, uint32_t kWorldSize, typename StatTrait>
+union BoundarySmem {
+  CommSmem<kRowsPerCTA, kWorldSize> comm;
+  MHCStatSmem<StatTrait> stats;
