+template <uint32_t kWorldSize>
+SGL_DEVICE void
+store_mxfp8_pair(const Params<kWorldSize>& params, const vec_t& o0, const vec_t& o1, uint64_t global_row, uint32_t v0) {
+  using namespace device;
