+/// \brief The inverse: two floats rounded into one packed bf16 pair.
+SGL_DEVICE uint32_t bf16_pack(float low, float high) {
+  uint32_t packed;
+  asm("cvt.rn.bf16x2.f32 %0, %1, %2;" : "=r"(packed) : "f"(high), "f"(low));
+  return packed;
