+        for (uint32_t half = 0; half < 2; ++half) {
+          Frag vec = residual_vec[buffer][i][half];
+#pragma unroll
+          for (uint32_t e = 0; e < 4; ++e) {
+            const auto [low, high] = bf16_unpack(vec[e]);
