+    float* out =
+        params.partial + static_cast<uint64_t>(tile * Trait::SPLIT_K + split_index) * M_TILE * Trait::kPartialStride;
+    for_each<Trait::kBlockSize, Trait::kTileVecs>([&](uint32_t i) {
+      Vec4 sum;
+      sum.fill(0.f);
+#pragma unroll
+      for (uint32_t slot = 0; slot < Trait::kNumReduceSlots; ++slot) {
