+/// which is why y and x cannot alias under the quantized all-gather.
+SGL_DEVICE uint64_t mxfp8_value_offset(uint64_t global_row, uint32_t vec_index) {
+  return global_row * kHidden + uint64_t(vec_index) * 8;
