+
+SGL_DEVICE uint64_t mxfp8_scale_offset(uint32_t total_rows, uint64_t global_row, uint32_t vec_index) {
+  return uint64_t(total_rows) * kHidden + global_row * (kHidden / 32) + (vec_index / 16) * 4;
+}
